// `any` satisfies every conditional: a signature returning it stays as it is, and counts as neither async nor stream.
type IsAny<T> = 0 extends 1 & T ? true : false;

type UnionToIntersection<U> = (U extends unknown ? (u: U) => void : never) extends (i: infer I) => void ? I : never;

/**
 * A parameter as a facade takes it: upstream's type, or the facade of any wrapped handle that type accepts (a
 * `StdioTransport` where upstream takes any `McpTransport`), borrowed or not. The runtime hands upstream the object a
 * facade wraps.
 */
export type Accepts<P, H extends HandleEntry> = IsAny<P> extends true ? P : P | AcceptedFacade<P, H>;

type AcceptedFacade<P, H extends HandleEntry> = H extends HandleEntry
	? [H[0]] extends [P]
		? H[1] | BorrowedFacade<H>
		: never
	: never;

/**
 * Every parameter of `A` as a facade takes it (`Accepts`), with each rewrite of `W` at its path (a secret also as
 * `Redacted`, an id as its brand); optional and rest parameters stay so.
 */
export type Accepting<A extends ReadonlyArray<unknown>, H extends HandleEntry, W extends Rewrite = never> = {
	[I in keyof A]: Rewritten<Accepts<A[I], H>, RewriteTail<W, I>>;
};

/** A path into a value: an argument's index, then property names (`["0", "auth", "pass"]`), or property names alone. */
export type SecretPath = ReadonlyArray<string>;

/**
 * What a facade's types change at the end of a path the recipe names: `"redacted"`, a secret also taken as
 * `Redacted` (the runtime reveals it to upstream in the call), `"concealed"`, a secret upstream keeps shown only as
 * `Redacted`, or a brand (`JobId`) a string carries, for types only.
 */
export type Rewrite = readonly [path: SecretPath, leaf: unknown];

/** The rewrites that take the secrets at the paths `P` also as `Redacted`. */
export type Redacting<P extends SecretPath> = P extends unknown ? readonly [P, "redacted"] : never;

/** The rewrites that show a secret upstream keeps at the paths `P` as `Redacted` only. */
export type Concealing<P extends SecretPath> = P extends unknown ? readonly [P, "concealed"] : never;

/** The rewrites that brand the strings at the paths `P` with `B`. */
export type Branding<P extends SecretPath, B> = P extends unknown ? readonly [P, B] : never;

/**
 * `T` with each rewrite of `W` at the end of its path. Objects on a path are copied field by field, unions
 * distributed; a union member the path does not reach (a string URL beside an options object) stays as it is.
 */
export type Rewritten<T, W extends Rewrite> = [W] extends [never] ? T : RewriteStep<T, W>;

type RewriteStep<T, W extends Rewrite> = [Ended<W>] extends [never]
	? T extends (...args: never) => unknown
		? T
		: T extends object
			? [Extract<keyof T, RewriteHead<W>>] extends [never]
				? T
				: { [K in keyof T]: K extends RewriteHead<W> ? RewriteStep<T[K], RewriteTail<W, K>> : T[K] }
			: T
	: Leaf<T, Ended<W>>;

// The leaf of a rewrite whose path ends here (an inferred rest is a mutable `[]`, which matches `readonly []`).
type Ended<W> = W extends readonly [readonly [], infer L] ? L : never;

type RewriteHead<W> = W extends readonly [readonly [infer Head extends string, ...ReadonlyArray<string>], unknown] ? Head : never;

type RewriteTail<W, K> = W extends readonly [readonly [infer Head, ...infer Rest extends SecretPath], infer L] ? (K extends Head ? readonly [Rest, L] : never) : never;

type Leaf<T, L> = L extends "redacted"
	? T | Redacted.Redacted<Exclude<T, null | undefined>>
	: L extends "concealed"
		? Extract<T, null | undefined> | Redacted.Redacted<Exclude<T, null | undefined>>
		: Branded<T, L>;

/**
 * `T` where each path of `P` ends taking its value also as `Redacted` (`Config.Redacted("SMTP_PASS")`), which the
 * facade reveals to upstream at the last moment.
 */
export type Secreted<T, P extends SecretPath> = Rewritten<T, Redacting<P>>;

/** `V` branded `B` where present: an id upstream types `string | undefined` is `JobId | undefined`. */
export type Branded<V, B> = Extract<V, null | undefined> | (Exclude<V, null | undefined> & B);

/** A facade function `F` whose Effects resolve with the brands of `W` at their paths: types only, values are upstream's. */
