	<E, H extends HandleEntry, O extends boolean = false, S extends SecretPath = never, Wraps extends boolean = true>() =>
	<A extends ReadonlyArray<unknown>, R>(method: (...args: A) => R): ((...args: Accepting<A, H>) => MethodResult<R, E, Given<H, Wraps>, O, S>) =>
		method as never;

/**
 * A lifted method's result as `Disagreeing` reads it: upstream method `F`'s result at its type parameters'
 * constraints, in facade form as `lifted` types it. The lifted type itself, generic with a rest parameter mapped
 * through `Accepting` (`Page.$$eval`), leaves the checker undecided.
 */
export type LiftedResult<F, E, H extends HandleEntry, O extends boolean = false, S extends SecretPath = never, Wraps extends boolean = true> = F extends (
	...args: never
) => infer R
	? () => MethodResult<R, E, Given<H, Wraps>, O, S>
	: never;

/**
 * One exported function in facade form: like a method, but a synchronous call becomes an `Effect` too (it may
 * throw); with `O`, a value that may be absent becomes an `Option`.
 */
export type FunctionSignature<F, E, H extends HandleEntry, O extends boolean = false, W extends Rewrite = never> = F extends (...args: infer A) => infer R
	? IsCallbackStyle<A, R> extends true
		? never
		: (...args: Accepting<A, H, W>) => FunctionResult<R, E, H, O>
	: never;

// What an exported function's result becomes. Not distributed over `R`: a value that may be absent (`Handle | null`)
// is one `Option`, and a function that may return a promise (`X | Promise<X>`) one Effect of `X`, as the runtime runs them.
// A function that only throws (`never`) is an Effect that fails: `never` would pass every check below, the iterable's too.
type FunctionResult<R, E, H extends HandleEntry, O extends boolean> = [R] extends [never]
	? Effect.Effect<never, E>
	: IsAny<R> extends true
		? Effect.Effect<R, E>
		: [Extract<R, PromiseLike<unknown>>] extends [never]
			? IsHandle<R, H> extends true
				? Resolved<R, E, H>
				: [R] extends [AsyncIterable<infer V>]
					? Stream.Stream<V, E>
					: O extends true
						? ResolvedOption<R, E, H>
						: Resolved<R, E, H>
			: O extends true
				? ResolvedOption<Awaited<R>, E, H>
				: Resolved<Awaited<R>, E, H>;

// A signature whose last parameter is a function and that returns nothing reports its result through that callback:
// its promise twin is the facade's, so it is left out.
type IsCallbackStyle<A extends ReadonlyArray<unknown>, R> = A extends readonly [...ReadonlyArray<unknown>, infer Last]
	? Last extends (...args: never) => unknown
		? [R] extends [void]
			? true
			: false
		: false
	: false;

/**
 * A method with every overload kept, each in facade form. A method whose every overload takes a trailing callback and
 * returns nothing, and which the generator does not list as reporting through it (`CallbackMethod`), takes the
 * callback as an argument like any other (a key handler): it stays as upstream types it.
 */
export type EffectMethod<
	F,
	E,
	H extends HandleEntry,
	O extends boolean = false,
	W extends Rewrite = never,
	S extends SecretPath = never,
	Async extends boolean = false,
	Wraps extends boolean = true,
> = [MethodSignature<Signatures<F>, E, H, O, W, S, Async, Wraps>] extends [never] ? F : EveryOverload<F, E, H, O, W, S, Async, Wraps, false>;

/**
 * Every signature of `F` (up to 12) in facade form, as `MethodSignature` makes it, or `CallbackSignature` when
 * `Reporting`, intersected into one overloaded function; `F`'s one signature when the checker cannot split them. A
 * signature either leaves out (`never`) is `unknown`, which the intersection drops. Built signature by signature, never
 * by `UnionToIntersection`: inferring an intersection from a union compares its members with each other, so the facades
 * their parameters take, which may lead back to the very member being typed (ts-morph's
 * `Directory.getRelativePathTo(directory: Directory)`), and TypeScript fails with TS2615 at every use of the member.
 */
